<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRouter } from 'vue-router'
import { AlertCircle,BadgeCheck,ChevronRight,Circle,Film,Play,RefreshCw,Route,ShieldCheck } from '@lucide/vue'
import { createMediaJourney,getMediaJourneyWorkspace,recordMediaJourneyVisit } from '../api/competitionJourney'
import { useContextStore } from '../stores/context'
const router=useRouter(),context=useContextStore(),workspace=ref({courses:[],runs:[],truthfulness:null}),selectedRunId=ref(localStorage.getItem('edumatrix_media_journey_id')||''),courseId=ref(localStorage.getItem('edumatrix_course_id')||''),loading=ref(true),action=ref(''),error=ref(''),notice=ref('')
const run=computed(()=>workspace.value.runs.find(x=>x.id===selectedRunId.value)||workspace.value.runs[0]||null)
const nextStep=computed(()=>run.value?.steps.find(x=>!x.complete)||null)
function detail(e){const d=e?.detail||e?.response?.data?.detail;return d?.message||(typeof d==='string'?d:'')||e?.message||'操作失败'}
async function load(){loading.value=true;error.value='';try{workspace.value=await getMediaJourneyWorkspace();if(!courseId.value)courseId.value=workspace.value.courses[0]?.id||'';if(!selectedRunId.value&&workspace.value.runs.length)selectedRunId.value=workspace.value.runs[0].id;if(selectedRunId.value)localStorage.setItem('edumatrix_media_journey_id',selectedRunId.value)}catch(e){error.value=detail(e)}finally{loading.value=false}}
async function create(){action.value='create';error.value='';try{const created=await createMediaJourney({course_id:courseId.value||null,run_key:`media-judge-${Date.now()}`});selectedRunId.value=created.id;localStorage.setItem('edumatrix_media_journey_id',created.id);if(courseId.value){localStorage.setItem('edumatrix_course_id',courseId.value);await context.loadCourse(courseId.value)}notice.value='多媒体创作旅程已建立，完成状态只读取真实版本化资源';await load()}catch(e){error.value=detail(e)}finally{action.value=''}}
async function openStep(step){if(!run.value)return;action.value=step.key;error.value='';try{await recordMediaJourneyVisit(run.value.id,{step_key:step.key,route:step.route});localStorage.setItem('edumatrix_media_journey_id',run.value.id);if(run.value.course_id)localStorage.setItem('edumatrix_course_id',run.value.course_id);await router.push({path:step.route,query:{journey:run.value.id,course_id:run.value.course_id||undefined,step:step.key}})}catch(e){error.value=detail(e)}finally{action.value=''}}
function selectRun(id){selectedRunId.value=id;localStorage.setItem('edumatrix_media_journey_id',id)}
onMounted(load)
</script>
<template><main class="journey"><header><div><p class="eyebrow"><Route :size="14"/> FC5 media journey</p><h1>多媒体创作旅程</h1><p>课程章节 → 讲义 → 网页课件 → 数字人 / 音频 → 视频 → 视频后练习 → 资源包。</p></div><button class="icon" aria-label="刷新多媒体旅程" title="刷新" @click="load"><RefreshCw :size="17"/></button></header>
<p v-if="error" class="notice error"><AlertCircle :size="15"/>{{error}}</p><p v-if="notice" class="notice ok"><BadgeCheck :size="15"/>{{notice}}</p><p v-if="loading" class="notice"><RefreshCw class="spin" :size="15"/>正在恢复创作旅程</p>
<section v-if="!loading&&workspace.truthfulness" class="truth"><ShieldCheck :size="18"/><div><strong>版本证据驱动</strong><span>访问工作台不等于内容已创建；完成状态由服务端读取当前用户和课程的不可变资源版本。</span></div></section>
<template v-if="!loading"><section class="toolbar"><label><span>目标课程</span><select v-model="courseId" :disabled="Boolean(run)"><option value="">不限定课程</option><option v-for="course in workspace.courses" :key="course.id" :value="course.id">{{course.title}} · {{course.version}}</option></select></label><label v-if="workspace.runs.length"><span>历史运行</span><select :value="run?.id" @change="selectRun($event.target.value)"><option v-for="item in workspace.runs" :key="item.id" :value="item.id">{{item.status}} · {{item.progress.completed}}/7 · {{item.run_key}}</option></select></label><button class="primary" :disabled="Boolean(action)" @click="create"><Play :size="14"/>新建创作旅程</button></section>
<section v-if="!run" class="empty"><Film :size="38"/><h2>尚未开始多媒体创作旅程</h2><p>选择课程后建立独立运行，最终资源包必须冻结前置内容的精确版本。</p></section>
<template v-else><section class="progress"><div><span>完成进度</span><strong>{{run.progress.completed}} / {{run.progress.total}}</strong></div><div class="bar"><i :style="{width:`${run.progress.percent}%`}"/></div><div><span>运行状态</span><strong>{{run.status==='completed'?'已完成':'进行中'}}</strong></div><button v-if="nextStep" class="primary" @click="openStep(nextStep)">继续：{{nextStep.label}}<ChevronRight :size="14"/></button><span v-else class="complete"><BadgeCheck :size="15"/>七步创作闭环完成</span></section>
<section class="steps"><article v-for="(step,index) in run.steps" :key="step.key" :class="{done:step.complete,next:nextStep?.key===step.key}"><div class="index"><BadgeCheck v-if="step.complete" :size="16"/><Circle v-else :size="16"/>{{index+1}}</div><div class="body"><span>{{step.key}}</span><strong>{{step.label}}</strong><p>{{step.purpose}}</p><small>{{step.summary}}</small><code v-if="step.evidence_id">{{step.evidence_id}}</code></div><button class="secondary" :disabled="Boolean(action)" @click="openStep(step)">{{step.complete?'查看版本':'进入工作台'}}<ChevronRight :size="14"/></button></article></section>
<section class="audit"><div><span>访问记录</span><strong>{{run.visits.length}}</strong></div><p>访问轨迹只证明导航发生，不参与完成计数。资源包必须至少冻结讲义、课件和视频三个精确版本。</p></section></template></template></main></template>
<style scoped>.journey{max-width:1240px;margin:auto;color:#20272a;padding:4px 2px 42px}.journey header{display:flex;justify-content:space-between;align-items:flex-start;padding:24px 2px 20px;border-bottom:1px solid #dce2e5}.journey h1{font-size:24px;margin:6px 0}.journey header p:last-child{font-size:13px;color:#667177}.eyebrow{display:flex;align-items:center;gap:7px;color:#8a4c37;font-size:10px;font-weight:750;text-transform:uppercase}.icon{width:36px;height:36px;display:grid;place-items:center;border:1px solid #d8dfe2;background:#fff;border-radius:7px}.notice{display:flex;align-items:center;gap:7px;padding:11px 14px;background:#f4f7f8;font-size:10px}.notice.error{background:#fff1ef;color:#963f35}.notice.ok{background:#eef8f1;color:#276046}.truth{display:flex;align-items:center;gap:10px;padding:12px 15px;background:#f8f1ed;color:#714633;border-bottom:1px solid #e4cdc3}.truth div{display:flex;flex-wrap:wrap;gap:5px 14px}.truth strong{font-size:11px}.truth span{font-size:10px}.toolbar{display:grid;grid-template-columns:1fr 1.2fr auto;align-items:end;gap:12px;padding:16px 0;border-bottom:1px solid #dce2e5}.toolbar label{display:flex;flex-direction:column;gap:5px}.toolbar label span{font-size:8px;color:#748087}.toolbar select{height:36px;border:1px solid #d4dcdf;background:#fff;padding:0 9px;font-size:10px;min-width:0}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:6px;padding:9px 11px;font-size:10px;font-weight:650;cursor:pointer}.primary{background:#6f4534;color:#fff}.secondary{background:#f4eae5;color:#704838}.progress{display:grid;grid-template-columns:auto 1fr auto auto;align-items:center;gap:16px;padding:17px;background:#faf7f5;border-bottom:1px solid #dce2e5}.progress>div:not(.bar){display:flex;flex-direction:column}.progress span{font-size:8px;color:#748087}.progress strong{font-size:13px}.bar{height:6px;background:#eadfd9;overflow:hidden}.bar i{display:block;height:100%;background:#9a5a40}.complete{display:flex!important;align-items:center;gap:6px;color:#276046!important;font-size:10px!important}.steps{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:22px 0}.steps article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:12px;min-width:0;padding:15px;border:1px solid #dce2e5;background:#fff}.steps article.done{border-color:#bdd3c5;background:#f4faf6}.steps article.next{border-color:#d8b6a6}.index{display:flex;flex-direction:column;align-items:center;gap:3px;color:#65747a;font-size:8px}.done .index{color:#276046}.body{display:flex;min-width:0;flex-direction:column}.body>span{font-size:7px;color:#95583e}.body strong{font-size:12px}.body p{font-size:9px;color:#748087;margin:3px 0}.body small{font-size:8px;color:#5f7067}.body code{margin-top:4px;font-size:7px;color:#748087;overflow-wrap:anywhere}.audit{display:flex;align-items:center;gap:16px;padding:14px;border:1px solid #dce2e5;background:#f8fafb}.audit div{display:flex;flex-direction:column;min-width:70px}.audit span{font-size:8px;color:#748087}.audit strong{font-size:15px}.audit p{font-size:9px;color:#667177}.empty{min-height:340px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:9px;color:#748087}.empty h2{font-size:15px;color:#20272a}.empty p{font-size:10px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:800px){.toolbar,.progress,.steps{grid-template-columns:1fr}.progress .primary{width:100%}.steps article{grid-template-columns:auto 1fr}.steps article button{grid-column:1/-1;width:100%}.audit{align-items:flex-start;flex-direction:column}}@media(max-width:430px){.journey h1{font-size:21px}.truth{align-items:flex-start}.toolbar select{width:100%}}</style>
